suppressPackageStartupMessages({library(ComplexHeatmap);library(circlize);library(dendsort);library(grid);library(jsonlite)})
source(file.path(dirname(normalizePath(commandArgs(TRUE)[1])),'native_export.R'))
x<-readRDS(file.path(B,'matrices.rds'));states<-rownames(x$adjacency);mem<-x$membership[match(states,x$membership$subpopulation),];groups<-ifelse(is.na(mem$sub.community),mem$community,mem$sub.community);lev<-unique(groups);groups<-factor(groups,levels=lev)
combined<-x$adjacency;combined[is.na(combined)]<-0;tmp<-x$correlation;tmp[is.na(tmp)]<-0;combined<-combined+tmp
clfun<-function(m)as.dendrogram(dendsort(hclust(dist(combined[rownames(m),rownames(m),drop=FALSE]))))
plan<-unlist(lapply(lev,function(g){ss<-states[groups==g];ss[order.dendrogram(clfun(x$zscore[ss,,drop=FALSE]))]}));stopifnot(setequal(plan,states),!anyDuplicated(plan))
a<-x$adjacency;c<-x$correlation;a[upper.tri(a)]<-t(a)[upper.tri(a)];c[lower.tri(c)]<-t(c)[lower.tri(c)];diag(a)<-diag(c)<-0;mat<-a;stopifnot(!anyNA(mat));write.csv(data.frame(state=plan,group=groups[match(plan,states)]),file.path(B,'row-order.csv'),row.names=FALSE)
zcol<-colorRamp2(c(-4,-2,0,2,4),c('#663B8B','#B391C5','#FFFFFF','#F3B980','#D96C24'));acol<-colorRamp2(c(0,.25,.5,.75,1),c('#FFFFFF','#F4D6CF','#E98F7A','#CE554D','#8F2E37'));ccol<-colorRamp2(c(-1,-.5,0,.5,1),c('#39745A','#AAC9AE','#FFFFFF','#B899CE','#6F3B8A'))
cell<-.88;gap<-.6;bodyh<-91*cell+(length(lev)-1)*gap;cats<-setNames(c('#7EB6AD','#A7C8C2','#C1A9D0','#AFD1E2','#E0B590','#D7A5AD')[seq_along(lev)],lev)
marks<-intersect(c('Oli.2','Oli.3','Ast.1','Mic.2','OPC.1','Ast.3','Oli.6','Mic.12','Mic.13','Ast.10','Oli.7','Ast.5','OPC.3','Mic.6','Mic.7'),states)
ps<-as.numeric(sub('^[^_]+_','',colnames(x$zscore)));pscol<-colorRamp2(c(0,.3,1),c('#E5F1F1','#74B3B7','#285B78'))
pairs<-expand.grid(display_row=seq_along(plan),display_col=seq_along(plan));ii<-match(plan[pairs$display_row],states);jj<-match(plan[pairs$display_col],states);pairs$row_state<-states[ii];pairs$column_state<-states[jj];pairs$measure<-ifelse(pairs$display_row>pairs$display_col,'dynamics',ifelse(pairs$display_row<pairs$display_col,'correlation','identity'));pairs$value<-ifelse(pairs$display_row>pairs$display_col,a[cbind(ii,jj)],ifelse(pairs$display_row<pairs$display_col,c[cbind(ii,jj)],NA_real_));write.csv(pairs,file.path(B,'association-display.csv'),row.names=FALSE)
draw_figure<-function(){
 dyn<-Heatmap(x$zscore,name='Dynamics',col=zcol,width=unit(67*cell+1.2,'mm'),height=unit(bodyh,'mm'),row_split=groups,cluster_row_slices=FALSE,cluster_rows=clfun,row_dend_reorder=FALSE,row_dend_width=unit(5,'mm'),cluster_columns=FALSE,column_split=factor(sub('_.*','',colnames(x$zscore)),levels=c('ABA','prAD')),column_gap=unit(1.2,'mm'),row_gap=unit(gap,'mm'),show_row_names=FALSE,show_column_names=FALSE,row_title=lev,row_title_gp=gp(),row_title_rot=0,column_title=c('ABA','prAD'),column_title_gp=gp(),rect_gp=gpar(col='#FFFFFF',lwd=.12),show_heatmap_legend=FALSE,bottom_annotation=HeatmapAnnotation(Pseudotime=ps,col=list(Pseudotime=pscol),simple_anno_size=unit(1.2,'mm'),show_annotation_name=FALSE,show_legend=FALSE))
 markanno<-rowAnnotation(states=anno_mark(at=match(marks,states),labels=marks,labels_gp=gp(),link_width=unit(2,'mm'),padding=unit(.6,'mm')),show_annotation_name=FALSE)
 assoc<-Heatmap(mat,name='Association',col=acol,width=unit(91*cell+(length(lev)-1)*gap,'mm'),height=unit(bodyh,'mm'),row_split=groups,column_split=groups,cluster_rows=FALSE,cluster_columns=FALSE,cluster_column_slices=FALSE,column_order=match(plan,states),show_row_names=FALSE,show_column_names=FALSE,show_row_dend=FALSE,row_title=NULL,column_title=NULL,column_gap=unit(gap,'mm'),row_gap=unit(gap,'mm'),rect_gp=gpar(type='none'),show_heatmap_legend=FALSE,right_annotation=markanno,layer_fun=function(j,i,x,y,w,h,fill){col<-rep('#30343B',length(i));ri<-match(states[i],plan);cj<-match(states[j],plan);lo<-ri>cj;hi<-ri<cj;col[lo]<-acol(a[cbind(i[lo],j[lo])]);col[hi]<-ccol(c[cbind(i[hi],j[hi])]);grid.rect(x,y,w,h,gp=gpar(fill=col,col='white',lwd=.08))})
 lg<-list(Legend(title='Pseudotime',col_fun=pscol,at=c(0,.3,1),direction='horizontal',legend_width=unit(24,'mm'),title_gp=gp(),labels_gp=gp()),Legend(title='Scaled dynamics',col_fun=zcol,at=c(-4,-2,0,2,4),direction='horizontal',legend_width=unit(32,'mm'),title_gp=gp(),labels_gp=gp()),Legend(title='Dynamics similarity',col_fun=acol,at=c(0,.5,1),direction='horizontal',legend_width=unit(32,'mm'),title_gp=gp(),labels_gp=gp()),Legend(title='Spearman correlation',col_fun=ccol,at=c(-1,0,1),direction='horizontal',legend_width=unit(32,'mm'),title_gp=gp(),labels_gp=gp()))
 drawn<-draw(dyn+assoc,newpage=FALSE,ht_gap=unit(1.6,'mm'),heatmap_legend_list=lg,heatmap_legend_side='bottom',merge_legends=TRUE,padding=unit(c(6,3,6,3),'mm'))
 ro<-unlist(row_order(drawn,name='Dynamics'));stopifnot(identical(states[ro],plan));co<-unlist(column_order(drawn,name='Association'));stopifnot(identical(states[co],plan))
 metrics<<-c(bf_complexheatmap_cell_metrics(drawn,'Dynamics'),bf_complexheatmap_cell_metrics(drawn,'Association'))
 for(i in seq_along(lev))decorate_heatmap_body('Association',{grid.rect(gp=gpar(fill=NA,col='#555D63',lwd=.4))},row_slice=i,column_slice=i)
}
export_native(draw_figure,'ComplexHeatmap')
